      "promise_discharge": "7bef15ebed163a9c"
    }
  ],
  "counter_notes": [
    {
      "counter": "garrison",
      "direction": "up",
      "reason": "The duke's envoy brings reinforcements, increasing the garrison from 30 to 32."
    },
    {
      "counter": "grain",
      "direction": "up",
      "reason": "A bountiful harvest, aided by Eadric's large plot and the repaired mill, boosts grain stores from 500 to 877."
    },
    {
      "counter": "population",
      "direction": "up",
      "reason": "Branna delivers three babes, and the envoy's arrival brings a few new families, raising the population from 120 to 170.5."
    }
  ],
  "texture_line": "The season ends with the scent of fresh bread and the clang of the blacksmith's hammer, as the village braces for the duke's attention."
}

